create function public.impact_metrics(from_date date,to_date date) returns setof jsonb language plpgsql stable security definer set search_path='' as $$
declare m public.membership; coop uuid; participants integer; received numeric; accepted numeric; valorized numeric; packaged numeric; sales_value numeric; sold numeric; whey_input numeric; active_producers numeric; trained_producers numeric; completeness numeric; open_critical numeric; mock_minutes numeric; k record; metric numeric;
begin
 select * into m from public.membership where user_id=wise_auth.uid() and status='active';
 if m.user_id is null or not (m.roles && array['supervisor','manager','admin','food_safety','partner','donor']) then raise exception 'Dashboard permission required'; end if;
 if m.roles && array['admin','food_safety'] and wise_auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'AAL2 required'; end if;
 coop:=case when m.roles && array['admin','food_safety','partner','donor'] then null else m.cooperative_id end;
 select count(distinct completion.user_id) into participants from public.training_completion completion join public.membership member on member.user_id=completion.user_id where 'producer'=any(member.roles) and member.status='active' and (coop is null or completion.cooperative_id=coop) and completion.completed_at::date between from_date and to_date;
 select coalesce(sum(initial_quantity),0),coalesce(sum(initial_quantity) filter(where state='accepted'),0) into received,accepted from public.lot where type='whey' and (coop is null or cooperative_id=coop) and observed_at::date between from_date and to_date;
 select coalesce(sum(c.quantity),0) into valorized from public.consumption c join public.lot i on i.id=c.input_lot_id join public.lot o on o.id=c.output_lot_id where i.type='whey' and i.state='accepted' and o.state in ('released','closed') and (coop is null or c.cooperative_id=coop) and c.observed_at::date between from_date and to_date;
 select coalesce(sum(p.mass_kg),0) into packaged from public.packaging_detail p join public.lot l on l.id=p.batch_id join public.lot pl on pl.id=p.lot_id where l.state<>'rejected' and (coop is null or p.cooperative_id=coop) and pl.observed_at::date between from_date and to_date;
 select coalesce(sum(total/usd_rate),0),coalesce(sum(quantity),0) into sales_value,sold from public.sale where transaction_type='sale' and (coop is null or cooperative_id=coop) and observed_at::date between from_date and to_date;
 select coalesce(sum(c.quantity),0) into whey_input from public.consumption c join public.lot i on i.id=c.input_lot_id where i.type='whey' and c.output_lot_id in (select p.batch_id from public.packaging_detail p join public.lot pl on pl.id=p.lot_id join public.lot b on b.id=p.batch_id where b.state<>'rejected' and pl.observed_at::date between from_date and to_date) and (coop is null or c.cooperative_id=coop);
 select count(distinct activity.author) into active_producers from (select producer_id author,cooperative_id,observed_at from public.lot where type='batch' union all select author_id,cooperative_id,observed_at from public.operational_record union all select author_id,cooperative_id,observed_at from public.consumption) activity join public.membership member on member.user_id=activity.author where member.status='active' and 'producer'=any(member.roles) and activity.observed_at::date between from_date and to_date and (coop is null or activity.cooperative_id=coop);
 select count(*) into trained_producers from public.membership member where member.status='active' and 'producer'=any(member.roles) and (coop is null or member.cooperative_id=coop) and not exists(select 1 from public.training_module module where module.required and not exists(select 1 from public.training_completion completion where completion.user_id=member.user_id and completion.module_id=module.id and completion.completed_at::date<=to_date and (completion.expires_at is null or completion.expires_at::date>to_date)));
 select 100.0*count(*) filter(where exists(select 1 from public.operational_record r where r.lot_id=b.id and r.definition_key=checkpoint->>'key' and r.observed_at::date<=to_date))/nullif(count(*),0) into completeness from public.lot b join public.config_version version on version.id=b.config_version_id cross join lateral jsonb_array_elements(version.definition->'checkpoints') checkpoint where b.type='batch' and b.state<>'draft' and (checkpoint->>'required')::boolean and b.observed_at::date between from_date and to_date and (coop is null or b.cooperative_id=coop);
 select count(*) into open_critical from public.deviation where severity='critical' and observed_at::date<=to_date and (closed_at is null or closed_at::date>to_date) and (coop is null or cooperative_id=coop);
 select avg(extract(epoch from(completed_at-started_at))/60) into mock_minutes from public.recall where mock and completed_at is not null and completed_at::date between from_date and to_date and (coop is null or cooperative_id=coop);
 for k in select * from public.kpi_definition where not('donor'=any(m.roles)) or visibility like '%donor%' loop
 metric:=case k.id when 'KPI-01' then received when 'KPI-02' then accepted when 'KPI-03' then valorized when 'KPI-04' then 100*valorized/nullif(accepted,0) when 'KPI-05' then packaged when 'KPI-06' then packaged/nullif(whey_input,0) when 'KPI-07' then active_producers when 'KPI-08' then trained_producers when 'KPI-09' then completeness when 'KPI-10' then sales_value when 'KPI-11' then sold when 'KPI-12' then open_critical when 'KPI-13' then mock_minutes else null end;
 return next jsonb_build_object('id',k.id,'label',k.label,'definition',k.definition,'value',case when 'donor'=any(m.roles) and participants<5 then null else metric end,'suppressed',('donor'=any(m.roles) and participants<5),'unit','');
 end loop;
end $$;
grant execute on function public.impact_metrics(date,date) to authenticated;
